/**
 * Smoke test for Sprint E — Transform Controller (standalone, no HTTP needed).
 * Uses the real container wiring and the data generated by tests A-D.
 *
 * Run: npx tsx scripts/test-transform.controller.mjs
 */
import { readFile, writeFile } from 'node:fs/promises';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { container } from '../src/container/index.js';
import { TransformController } from '../src/controllers/transform.controller.js';
import { createLogger } from '../src/utils/logger.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const outputsRoot = join(__dirname, '..', 'outputs', 'QyW1rOk-qqI');

function assert(condition, message) {
  if (!condition) {
    console.error(`FAIL: ${message}`);
    process.exitCode = 1;
  } else {
    console.log(`ok: ${message}`);
  }
}

async function main() {
  // Load the script we generated in Sprint B
  const script = JSON.parse(await readFile(join(outputsRoot, 'metadata', 'script.json'), 'utf8'));
  const ttsResult = { outputPath: join(outputsRoot, 'voice', 'narration.mp3'), durationSeconds: 72 };

  // Build deps from container
  const logger = createLogger('test.transform');
  const deps = {
    youtubeService: {
      downloadVideo: async () => {
        throw new Error('Should not call download in dry-run mode');
      },
    },
    transcriptService: {
      loadTranscript: async (videoId) => {
        return JSON.parse(await readFile(join(outputsRoot, 'transcripts', `${videoId}.json`), 'utf8'));
      },
    },
    contentAngleService: container.contentAngleService,
    scriptService: container.scriptService,
    ttsService: container.ttsService,
    videoPlanService: container.videoPlanService,
    templateService: container.templateService,
    templateRendererService: container.templateRendererService,
    outputsDir: join(process.cwd(), 'outputs'),
    logger,
  };

  const controller = new TransformController(deps);

  // Test dry-run mode (no rendering)
  console.log('\n=== Testing DRY RUN ===');
  const dryRunResult = await controller.transform({
    videoId: 'QyW1rOk-qqI',
    candidateId: 0,
    selectedAngleId: 'angle_01',
    template: 'commentary',
    language: 'id',
    dryRun: true,
  });

  console.log('Response keys:', Object.keys(dryRunResult));
  assert(dryRunResult.success === true, 'success: true');
  assert(dryRunResult.dryRun === true, 'dryRun: true');
  assert(dryRunResult.videoId === 'QyW1rOk-qqI', 'videoId matches');
  assert(dryRunResult.script !== undefined, 'script included');
  assert(dryRunResult.narration !== undefined, 'narration included');
  assert(dryRunResult.videoPlan !== undefined, 'videoPlan included');
  assert(dryRunResult.angle !== undefined, 'angle included');

  // Test full run (with rendering fallback)
  console.log('\n=== Testing FULL RUN (render fallback) ===');
  const fullResult = await controller.transform({
    videoId: 'QyW1rOk-qqI',
    candidateId: 0,
    selectedAngleId: 'angle_01',
    template: 'commentary',
    language: 'id',
    dryRun: false,
  });

  console.log('Response keys:', Object.keys(fullResult));
  assert(fullResult.success === true, 'success: true');
  assert(fullResult.dryRun === false, 'dryRun: false');
  assert(fullResult.outputVideo !== undefined, 'outputVideo included');
  assert(fullResult.videoPlan.scenes.length > 0, 'scenes populated');
  assert(fullResult.script.sections.length > 0, 'script sections populated');

  // Save full result
  await writeFile(
    join(outputsRoot, 'metadata', 'transform-result.json'),
    JSON.stringify(fullResult, null, 2),
  );
  console.log('\nSaved to outputs/QyW1rOk-qqI/metadata/transform-result.json');
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
